/* lxqw offline mock server - v0.3.0 */
(function () {
  "use strict";
  function fmt(o){ try{ var s=JSON.stringify(o); return s&&s.length>600?s.slice(0,600)+"...":s; }catch(e){ return "<unstringifiable>"; } }
  function lg(m){ try{ console.log("[MOCK] "+m); }catch(e){} }
  function wn(m){ try{ console.warn("[MOCK] "+m); }catch(e){} }

  function flexFn(){ return flex(); }
  function flex() {
    var t = flexFn;
    return new Proxy(t, {
      get: function (tt, k) {
        if (k === "then") return undefined;
        if (k === "length") return 0;
        if (k === "prototype") return tt.prototype;
        if (k === "toJSON") return function(){ return null; };
        if (k === Symbol.toPrimitive) return function(h){ return h === "string" ? "" : 0; };
        if (k === "valueOf") return function(){ return 0; };
        if (k === "toString") return function(){ return ""; };
        if (k === Symbol.iterator) return function(){ return { next: function(){ return { done: true, value: undefined }; } }; };
        if (k === "constructor") return Object;
        if (typeof k === "symbol") return undefined;
        return flex();
      },
      has: function(){ return true; },
      ownKeys: function(){ return []; },
      getOwnPropertyDescriptor: function(){ return undefined; },
      apply: function(){ return flex(); },
      construct: function(){ return flex(); }
    });
  }
  var MISSING = flex();

  var Mock = window.MockServer = {
    version: "0.3.0",
    handlers: {},
    state: { clover: 1000, ticket: 10, account: "offline", uid: 10001 },
    handle: function (name, params) {
      var h = Mock.handlers[name];
      if (!h) { wn("NO-HANDLER "+name); return MISSING; }
      try { var r = h(params); lg("RESP "+name+" "+fmt(r)); return (r === undefined || r === null) ? {} : r; }
      catch (e) { wn("HANDLER-ERR "+name+" "+(e&&e.stack||e)); return MISSING; }
    }
  };

  /* ---------------- login / hall ---------------- */
  Mock.handlers["client_hello"] = function(){ return { timestamp: Math.floor(Date.now()/1000) }; };
  Mock.handlers["hall_gen_token"] = function(){ return { code:0, token:"offline-token" }; };
  Mock.handlers["hall_login"] = function(){ return { code:0, account:Mock.state.account }; };
  Mock.handlers["hall_reconnect"] = function(){ return { code:0, account:Mock.state.account }; };
  Mock.handlers["hall_enter_game"] = function(){ return { code:0 }; };
  Mock.handlers["client_load_role"] = function(){
    return { uid: Mock.state.uid,
      res: { clover_point: Mock.state.clover, ticket: Mock.state.ticket },
      settings: { client: "{}", push_switch: 0, rank_switch: 0 },
      frog: { name:"xiaowa", cur_achieve:0, achieves:[], achieves_time:[], status:0, motion:0,
              icon:0, pic_show:1, today_step:0, decoration:[], taobao_data:{} } };
  };
  Mock.handlers["client_load_all_info"] = function(){ return {}; };
  Mock.handlers["annual_load"] = function(){ return { is_share: false, list: [] }; };

  /* ---------------- startup loads ---------------- */
  Mock.handlers["client_load_events"] = function(){ return []; };
  Mock.handlers["client_load_publicity"] = function(){ return { id_list: [] }; };
  Mock.handlers["client_load_decorate"] = function(){ return { has_list: [], put_id: 0, status: 0 }; };
  Mock.handlers["clover_load_clovers"] = function(){ return []; };
  Mock.handlers["clover_update"] = function(){ return { clover: Mock.state.clover }; };
  Mock.handlers["weather_load"] = function(){ return {}; };
  Mock.handlers["travel_load_note"] = function(){ return { note_list: [] }; };
  Mock.handlers["travel_load_gift"] = function(){ return { list: [] }; };
  Mock.handlers["item_load_items"] = function(){
    return { house: [], bag: [], desk: [], bag_completed: 0, bag_conflict: 0, desk_conflict: 0, gacha: { color_ball: -1 } };
  };
  Mock.handlers["furniture_load_furniture"] = function(){
    return { shop: { shop_list: [], start_time: 0, leave_time: 0 }, replace_fur: [], box_list: [], compost_list: [], tumbler_list: [] };
  };
  Mock.handlers["furniture_load_pocket"] = function(){ return { list: [] }; };
  Mock.handlers["furniture_load_compost"] = function(){ return { box_list: [], compost_list: [] }; };
  Mock.handlers["furniture_load_tumbler"] = function(){ return { tumbler_list: [] }; };
  Mock.handlers["task_load"] = function(){ return { tasks: [], list: [] }; };
  Mock.handlers["story_load"] = function(){ return { stories: [], new_story_id: 0 }; };
  Mock.handlers["rank_load"] = function(){ return { info: [], first_intro: null }; };
  Mock.handlers["visit_load"] = function(){ return {}; };
  Mock.handlers["other_load_touch"] = function(){ return { cur: 0, list: [] }; };
  Mock.handlers["misc_moment_load"] = function(){ return { list: [] }; };
  Mock.handlers["share_load"] = function(){ return { pic_list: [] }; };
  Mock.handlers["easteregg_load"] = function(){ return { egg_list: [] }; };
  Mock.handlers["adsmgr_load"] = function(){ return { item_list: [] }; };
  Mock.handlers["encyclopedia_load"] = function(){ return { unlock_list: [], unlock_desc: [], show_sub: [] }; };
  Mock.handlers["encytravel_load"] = function(){ return { unlock_list: [], unlock_desc: [], show_sub: [] }; };
  Mock.handlers["capsule_load"] = function(){ return { task_list: [], patch_num: 0, coin: 0, pre_coin: 0 }; };
  Mock.handlers["animpicture_load"] = function(){ return { pic_list: [], making_index: 0 }; };
  Mock.handlers["album_load"] = function(){ return { pictures: [], start: 0, total: 0 }; };
  Mock.handlers["album_load_all"] = function(){ return { id_list: [] }; };
  Mock.handlers["calendar_load"] = function(){ return { lucky_days: [], new_flag: [], st_days: [], task_list: [], note_list: [] }; };
  Mock.handlers["calendar_load_note"] = function(){ return { list: [] }; };
  Mock.handlers["greetcard_load"] = function(){ return { card_info: {} }; };
  Mock.handlers["springcard_load"] = function(){ return { card_info: {} }; };
  Mock.handlers["guest_load_drawing"] = function(){ return { colls: [], pages: [] }; };
  Mock.handlers["wishingpool_load"] = function(){ return { wish_list: [] }; };
  Mock.handlers["lottery_load"] = function(){ return { list: [] }; };
  Mock.handlers["mail_load"] = function(){ return { mails: [], list: [] }; };
  Mock.handlers["museum_load"] = function(){ return { list: [] }; };
  Mock.handlers["museumday_load"] = function(){ return { list: [] }; };
  Mock.handlers["partycake_load"] = function(){ return { list: [] }; };
  Mock.handlers["pray_load_grays"] = function(){ return { list: [] }; };
  Mock.handlers["recharge_load_gift"] = function(){ return { list: [] }; };
  Mock.handlers["cooking_load_cooking"] = function(){ return { list: [], task_list: [] }; };
  Mock.handlers["client_load_events"] = Mock.handlers["client_load_events"];

  /* ---------------- plumbing ---------------- */
  function callCb(cb, resp, sent) {
    if (cb == null) return false;
    try {
      if (typeof cb.apply === "function") { cb.apply(resp, sent); return true; }
      if (typeof cb === "function") { cb.call(resp); return true; }
      if (typeof cb.execute === "function") { cb.execute(); return true; }
    } catch (e) { wn("callback err: "+(e&&e.message||e)); }
    return false;
  }
  function dispatchEvent(name, resp, sent) {
    var d = core.ServiceDispatcher.getInstance();
    if (d.hasEventListener(name)) { lg("DISPATCH "+name); d.dispatchEvent(new core.Event(name, resp, sent)); return true; }
    return false;
  }
  function patchSDK() {
    var done = [];
    function patchInst(o, label) {
      if (!o || o.__mockPatched) return;
      try {
        o.__mockPatched = 1;
        o.Login = function(){ lg("SDK.Login stub "+label); return Promise.resolve({ code:0, token:"offline-token", game_token:"offline-game-token", ptoken:"offline-ptoken", pinfo:{ user_id:Mock.state.uid, user_name:Mock.state.account, nick_name:Mock.state.account, platform:"ONE", channel:"P10528" } }); };
        if (o.jsInvokeLua) o.jsInvokeLua = function(){ lg("jsInvokeLua stub "+label+" "+arguments[0]+"."+arguments[1]); return Promise.resolve({}); };
        if (o.jsInvokeLuaUseLongCallback) o.jsInvokeLuaUseLongCallback = function(){ lg("jsInvokeLuaLong stub "+label); return Promise.resolve({}); };
        done.push(label);
      } catch(e) { wn("patchInst fail "+label+" "+e); }
    }
    try { if (window.ALISDK) {
      if (ALISDK.LoginSDK && ALISDK.LoginSDK.instance) patchInst(ALISDK.LoginSDK.instance(), "LoginSDK");
      if (ALISDK.Platform && ALISDK.Platform.FTGameSDK && ALISDK.Platform.FTGameSDK.instance) patchInst(ALISDK.Platform.FTGameSDK.instance(), "FTGameSDK");
      if (ALISDK.AnnSDK && ALISDK.AnnSDK.instance) patchInst(ALISDK.AnnSDK.instance(), "AnnSDK");
    } } catch(e) { wn("ALISDK patch "+e); }
    try { if (window.EjoySDK && EjoySDK.instance) patchInst(EjoySDK.instance(), "EjoySDK"); } catch(e) {}
    lg("sdk patched: "+done.join(","));
  }
  function install() {
    if (typeof core === "undefined" || !core.SocketManage || typeof ProtocolList === "undefined" || !ProtocolList.protocolList) {
      return setTimeout(install, 30);
    }
    if (Mock.state.installed) return;
    Mock.state.installed = true;
    var SM = core.SocketManage.prototype;
    SM.send = function (name, callback) {
      var args = Array.prototype.slice.call(arguments, 2);
      var def = ProtocolList.protocolList[name];
      if (!def) { wn("unknown protocol "+name); return; }
      var pnames = def[0] || [];
      var wants = def[1];
      var params = {};
      for (var i=0;i<pnames.length;i++) params[pnames[i]] = args[i];
      var hasCb = (callback != null);
      lg("REQ "+name+" cb="+(hasCb?("yes/"+(typeof callback)):"no")+" wants="+!!wants+" "+fmt(params));
      var resp = Mock.handle(name, params);
      if (resp == null) return;
      if (!wants && !hasCb) { lg("SKIP-RESP "+name); return; }
      setTimeout(function () {
        var okd = dispatchEvent(name, resp, params);
        var okc = callCb(callback, resp, params);
        if (!okd && !okc) wn("NO-CONSUMER "+name);
      }, 0);
    };
    if (core.Socket) {
      var SP = core.Socket.prototype;
      SP.connect = function(h,p,t){ var s=this; lg("fake connect "+h+":"+p); setTimeout(function(){ s.socket_Connect(); }, 10); };
      SP.connectByUrl = function(u,t){ var s=this; lg("fake connectByUrl "+u); setTimeout(function(){ s.socket_Connect(); }, 10); };
      SP.send = function(d){ lg("socket.send drop: "+String(d).slice(0,200)); };
    }
    try { patchSDK(); } catch(e) { wn("sdk patch "+e); }
    lg("installed v"+Mock.version);
  }
  install();
})();
